      question_id: "SRM_C6_MEDIUM_001_3",
      question: "Under Activity Based CVP, what is the total monthly cost of setups under the existing production arrangement?",
      options: [
        "₹1,20,000",
        "₹1,60,000",
        "₹2,00,000",
        "₹2,40,000"
      ],
      answer: 1,
      reason: "40 setups × ₹4,000 per setup = ₹1,60,000."
